import React, { useState } from "react";
import { Link } from "react-router-dom";
import axios from "axios";
import GeneralContext from "./GeneralContext";
import "./BuyActionWindow.css";

const BuyActionWindow = ({ uid }) => {
  const [stockQuantity, setStockQuantity] = useState(1);
  const [stockPrice, setStockPrice] = useState(0.0);

  const handleBuyClick = async () => {
    try {
      await axios.post("http://localhost:3002/newOrder", {
        name: uid,
        qty: Number(stockQuantity),
        price: Number(stockPrice),
        mode: "BUY",
      });
      alert("✅ Buy order placed");
      GeneralContext.closeBuyWindow();
    } catch (err) {
      console.error("Buy error:", err);
      alert("❌ Error placing buy order");
    }
  };

  const handleSellClick = async () => {
    try {
      // Try to place sell — backend will validate holdings and respond 400 if not enough
      const resp = await axios.post("http://localhost:3002/sellOrder", {
        name: uid,
        qty: Number(stockQuantity),
        price: Number(stockPrice),
        mode: "SELL",
      });

      alert("✅ Sell order placed");
      GeneralContext.closeBuyWindow(); // or closeSellWindow() if you have it
    } catch (err) {
      console.error("Sell error:", err);

      // If backend returned 400 with text "Not enough holdings to sell"
      if (err.response && err.response.status === 400) {
        alert(err.response.data || "You don't have enough holdings to sell.");
      } else {
        alert("❌ Error placing sell order");
      }
    }
  };

  const handleCancelClick = () => {
    GeneralContext.closeBuyWindow();
  };

  return (
    <div className="container" id="buy-window" draggable="true">
      <div className="regular-order">
        <div className="inputs">
          <fieldset>
            <legend>Qty.</legend>
            <input
              type="number"
              name="qty"
              id="qty"
              onChange={(e) => setStockQuantity(e.target.value)}
              value={stockQuantity}
              min="1"
            />
          </fieldset>
          <fieldset>
            <legend>Price</legend>
            <input
              type="number"
              name="price"
              id="price"
              step="0.05"
              onChange={(e) => setStockPrice(e.target.value)}
              value={stockPrice}
            />
          </fieldset>
        </div>
      </div>

      <div className="buttons">
        <span>Margin required ₹140.65</span>
        <div>
          <Link className="btn btn-blue" onClick={handleBuyClick}>
            Buy
          </Link>

          {/* Sell Button */}
          <Link className="btn btn-red" onClick={handleSellClick}>
            Sell
          </Link>

          <Link to="" className="btn btn-grey" onClick={handleCancelClick}>
            Cancel
          </Link>
        </div>
      </div>
    </div>
  );
};

export default BuyActionWindow;
